    run.state.status = 'completed'; run.state.message = `${diagrams.length === 1 ? 'Diagram' : `${diagrams.length} diagrams`} created beside the anchor`;
  }
  dispose() { for (const run of this.runs.values()) this.cancel(run.state.runId); }
}

function findParent(box: GridBox, id: string): Extract<GridBox, { kind: 'container' }> | undefined {
  if (box.kind !== 'container') return undefined;
  return box.children.some(child => child.id === id) ? box : box.children.map(child => findParent(child, id)).find(Boolean);
}
"},{"path":"application/mapping/agent/diagramBatchService.ts","text":"import { randomUUID } from 'node:crypto';
import type { DiagramGenerator } from '../../../domain/core/diagrams/diagramGeneration';
import type { DiagramAgentContextStore } from '../../../domain/core/diagrams/diagramAgentContext';
import { DiagramEditService, type DiagramEditCanvasPort } from './diagramEditService';
import { directBatchSchemas, generationBatchSchemas, type DiagramBatchApplication, type DiagramBatchRun, type DiagramTool } from '../../../domain/mapping/agent/diagramBatch';
import { findBox } from '../../../domain/mapping/workspace/canvasDisplayNode';

interface Batch { signature: string; state: DiagramBatchRun; pending?: Promise<void>; child?: DiagramEditService; childRunId?: string; application?: DiagramBatchApplication; sessionId: string }
export class DiagramBatchService {
  private runs = new Map<string, Batch>();
  private requests = new Map<string, string>();
  constructor(private diagrams: DiagramGenerator, private canvas: DiagramEditCanvasPort & {
    batch(sessionId: string, input: DiagramBatchApplication): Promise<{ version: number; unresolvedEdgeIds: string[] }>
  }, private contexts?: DiagramAgentContextStore, private contextFor?: (sessionId: string, contextId: string) => import('../../../domain/core/agents/agentContext').AgentContextSnapshot | Promise<import('../../../domain/core/agents/agentContext').AgentContextSnapshot>) {}
  has(id: string) { return this.runs.has(id); }
  get(id: string) { const batch = this.runs.get(id); if (!batch) throw Error('Batch not found'); return structuredClone(batch.state); }
  async wait(id: string) { await this.runs.get(id)?.pending; return this.get(id); }
  cancel(id: string) {
    const batch = this.runs.get(id); if (!batch) throw Error('Batch not found');
    if (batch.state.status === 'generating') { batch.state.status = 'cancelled'; if (batch.childRunId) batch.child?.cancel(batch.childRunId); }
    return this.get(id);
  }
  start(raw: unknown, operation: DiagramTool, direct: boolean) {
    const input = (direct ? directBatchSchemas : generationBatchSchemas)[operation].parse(raw);
    const key = JSON.stringify([input.sessionId, input.requestId]), signature = JSON.stringify({ input, operation, direct });
    const old = this.requests.get(key);
    if (old) {
      const batch = this.runs.get(old)!;
      if (batch.signature !== signature) throw Error('REQUEST_ID_CONFLICT: batch arguments differ');
      if (batch.state.status === 'awaiting-acknowledgement' && !batch.pending) this.launch(batch, () => this.apply(batch));
      return this.get(old);
    }
    if (this.runs.size >= 500) throw Error('Diagram batch capacity reached; restart backend');
    const runId = `diagram-batch-${randomUUID()}`;
    const batch: Batch = { signature, sessionId: input.sessionId, state: { runId, operation, status: 'generating', results: [] } };
    this.runs.set(runId, batch); this.requests.set(key, runId);
    this.launch(batch, async () => {
      const revisions = input.operations.flatMap(item => [item.baseRevisionId, ...('references' in item ? item.references ?? [] : []).map(ref => ref.revisionId)]);
      const snapshot = await this.canvas.snapshot(input.sessionId, revisions.filter(id => id !== 'canvas'));
      if (snapshot.version !== input.expectedVersion) throw Error('VERSION_CONFLICT: reread the canvas');
      const application: DiagramBatchApplication = { requestId: runId, expectedVersion: input.expectedVersion, edits: [], creations: [] };
      // All inputs address the same snapshot. Multiple edits of one shared diagram would be ambiguous.
      const targets = new Set<string>();
      for (let index = 0; index < input.operations.length; index++) {
        batch.state.operationIndex = index;
        const item = input.operations[index], box = findBox(snapshot.document.scene.root, item.nodeId.slice(5));
        if (operation === 'edit-diagram' && box?.kind === 'diagram') {
          const id = snapshot.document.scene.contents[box.contentId].diagramId;
          if (targets.has(id)) throw Error('BATCH_TARGET_CONFLICT: combine edits to the same diagram in one operation');
          targets.add(id);
        }
      }
      let autoOffset = 0;
      for (let index = 0; index < input.operations.length; index++) {
        if (batch.state.status === 'cancelled') return;
        batch.state.operationIndex = index;
        const item = input.operations[index];
        const child = new DiagramEditService(this.diagrams, {
          snapshot: async (_id, ids) => {
            const extra = (ids ?? []).filter(id => id !== 'canvas' && !snapshot.revisions?.some(revision => revision.id === id));
            const retained = extra.length ? await this.canvas.snapshot(input.sessionId, extra) : undefined;
            if (retained && retained.version !== snapshot.version) throw Error('VERSION_CONFLICT: canvas changed');
            return { ...snapshot, revisions: [...(snapshot.revisions ?? []), ...(retained?.revisions ?? [])] };
          },
          apply: async (_id, edit) => { application.edits.push(edit); return { version: snapshot.version, unresolvedEdgeIds: [] }; },
          create: async (_id, creation) => {
            for (const diagram of creation.diagrams) {
              if (!item.origin) { diagram.position.column += autoOffset; autoOffset += Math.max(...diagram.content.ascii.split('\n').map(line => line.length)) + 6; }
              application.creations.push(diagram);
            }
            return { version: snapshot.version };
          }
        }, this.contexts);
        batch.child = child;
        const { edit, diagram, ...fields } = item as typeof item & { edit?: import('../../../domain/core/diagrams/generatedDiagramEdit').GeneratedDiagramEdit; diagram?: import('../../../domain/core/diagrams/generatedDiagramEdit').GeneratedDiagramEdit };
        const context = 'agentContextId' in fields && fields.agentContextId ? await this.contextFor?.(input.sessionId, fields.agentContextId) : undefined;
        if (this.get(runId).status === 'cancelled') return;
        const childRun = child.start({ ...fields, prompt: 'prompt' in fields ? fields.prompt : 'Apply supplied diagram',
          sessionId: input.sessionId, expectedVersion: snapshot.version, requestId: `${runId}:${index}` }, context, operation, direct ? edit ?? diagram : undefined);
        batch.childRunId = childRun.runId;
        const result = await child.wait(childRun.runId);
        if (this.get(runId).status === 'cancelled') return;
        if (result.status !== 'completed') throw Error(result.error ?? `Operation ${index} ${result.status}`);
        batch.state.results.push({ operationIndex: index, ...(result.agentContextId ? { agentContextId: result.agentContextId, agentContextHash: result.agentContextHash } : {}), result: result.result, variants: result.variants, created: result.created });
      }
      batch.child = undefined; batch.childRunId = undefined; delete batch.state.operationIndex;
      batch.application = application;
      await this.apply(batch);
    });
    return this.get(runId);
  }
  private launch(batch: Batch, work: () => Promise<void>) {
    batch.pending = work().catch(error => {
      if (batch.state.status === 'cancelled') return;
      const message = String(error);
      batch.state.status = batch.state.status === 'applying' && /PERSISTENCE_PENDING|CANVAS_TIMEOUT|CANVAS_UNAVAILABLE/.test(message)
        ? 'awaiting-acknowledgement' : message.includes('VERSION_CONFLICT') ? 'conflict' : 'failed';
      batch.state.error = `${batch.state.operationIndex === undefined ? '' : `operations[${batch.state.operationIndex}]: `}${message}`;
    }).finally(() => { batch.pending = undefined; });
  }
  private async apply(batch: Batch) {
    batch.state.status = 'applying'; delete batch.state.error;
    const receipt = await this.canvas.batch(batch.sessionId, batch.application!);
    for (const result of batch.state.results) {
      if (result.result) { result.result.documentVersion = receipt.version; result.result.unresolvedEdgeIds = receipt.unresolvedEdgeIds; }
      if (result.created) result.created.documentVersion = receipt.version;
    }
    batch.state.documentVersion = receipt.version; batch.state.status = 'completed';
  }
  dispose() { for (const id of this.runs.keys()) this.cancel(id); }
}
"},{"path":"domain/core/diagrams/diagramGeneration.ts","text":"import type { AgentContextSnapshot } from '../agents/agentContext';
import type { Diagram, DiagramInput } from './diagram';
import type { SubtreeRange } from './diagramSubtreeEdit';

/** The parts of a template parameter that rendering needs. */
export type GenerationPromptParameter =
  | { kind: 'enum'; key: string; options: readonly { value: string; guidance: string }[] }
  | { kind: 'number'; key: string };
export interface DiagramGenerationRequest {
  /** Authoritative parsed-node -> logical-node identities, supplied by the revision model. */
  nodeRefs?: Readonly<Record<string, string>>;
  agentContext?: AgentContextSnapshot;
  llmSessionId?: string;
  input: Omit<DiagramInput, 'revision' | 'ascii'>;
  instruction: string;
  /** Structured prompt: a validated template with options plus resolved, revision-pinned references. */
  prompt?: {
    markdown: string;
    options: Readonly<Record<string, string | number>>;
    parameters: readonly GenerationPromptParameter[];
    references: readonly unknown[];
  };
  baseRevisionId?: string;
  operation?: 'edit-diagram' | 'create-diagram' | 'extend-diagram';
  sourceMappings?: boolean;
  editRange?: SubtreeRange;
  editRanges?: SubtreeRange[];
  context?: {
    diagram: Diagram;
    connections?: readonly import('./diagramConnection').DiagramConnection[];
    selection: { startLine: number; endLine: number; startColumn: number; endColumn: number };
    projectId?: string; representationId?: string; baseRevisionId?: string;
  };
}
export interface GenerationOptions {
  signal?: AbortSignal; onProgress?: (message: string) => void;
  onAgentSession?: (sessionId: string) => void;
  onAgentContext?: (context: AgentContextSnapshot) => void;
}
export interface DiagramGenerator {
  generate(request: DiagramGenerationRequest, options: GenerationOptions): Promise<Omit<DiagramInput, 'id' | 'revision'> & { nodeCorrespondence?: Record<string, number>; replacementRanges?: SubtreeRange[] }>;
}
"},{"path":"domain/core/diagrams/generatedDiagramEdit.ts","text":"import { z } from 'zod';
import { buildDiagramContent } from './diagramContent';
import { validateDiagram, type Diagram } from './diagram';
import { stripNodeContinuity } from './diagramNodeContinuity';
import { diagramContentNodes } from './diagramContentNodes';

export const generatedDiagramEditSchema = z.object({
  // Identity annotations are removed before enforcing the 20,000-character content limit.
  ascii: z.string().min(1).max(200000),
  structureKind: z.enum(['diagram', 'tree']),
  replacementRanges: z.array(z.object({ startLine: z.number().int().positive(), endLine: z.number().int().nonnegative() }).strict()).min(1).max(100).optional(),
  mappings: z.array(z.object({ id: z.string().min(1), entityId: z.string().min(1),
    sourceRangeIndex: z.number().int().nonnegative(), sourceRangeId: z.string().optional(),
    line: z.number().int().positive(), startColumn: z.number().int().positive(), endColumn: z.number().int().positive()
  }).strict()).max(2000).optional()
}).strict();
export type GeneratedDiagramEdit = z.infer<typeof generatedDiagramEditSchema>;

/** Validate an agent candidate without issuing a revision for rejected submissions. */
export function validateGeneratedDiagramEdit(base: Diagram, raw: unknown, nodeRefs: Readonly<Record<string, string>> = {}, sourceMappings = false): GeneratedDiagramEdit & { nodeCorrespondence: Record<string, number> } {
  const parsed = generatedDiagramEditSchema.parse(raw);
  if (!sourceMappings && parsed.mappings?.length) throw Error('SOURCE_MAPPINGS_DISABLED: omit mappings or enable source-mappings');
  if (sourceMappings && !parsed.mappings) throw Error('SOURCE_MAPPINGS_REQUIRED: supply mappings (an empty array is allowed)');
  const candidate = { ...parsed, ...stripNodeContinuity(parsed.ascii, nodeRefs) };
  if (!candidate.ascii.trim() || candidate.ascii.includes('\r') || candidate.ascii.includes('\t'))
    throw Error('Use nonempty ASCII with LF newlines and spaces, not tabs');
  const content = buildDiagramContent(candidate.ascii, `${base.id}:${base.revision + 1}`, candidate.structureKind);
  for (const line of Object.values(candidate.nodeCorrespondence)) if (diagramContentNodes(content).filter(node => node.line === line).length !== 1)
    throw Error('CONTINUITY: marker must identify exactly one output node');
  validateDiagram({ ...base, revision: base.revision + 1, content, jumps: undefined,
    sourceContext: { ...base.sourceContext, contentHash: content.asciiSha256, mappings: candidate.mappings ?? [] } });
  return candidate;
}
"},{"path":"infrastructure/mapping/agent-chat/codexConnection.ts","text":"import { spawn, type ChildProcessWithoutNullStreams } from 'node:child_process';
import { createInterface } from 'node:readline';
import { requireAiEnabled } from '../../../application/core/errors';
import type { CodexConnection, CodexMessage } from '../../../application/mapping/agent-chat/ports';

/** T3 Code's stdio app-server lifecycle, adapted to this app's service boundary. */
export class StdioCodexConnection implements CodexConnection {
  private child?: ChildProcessWithoutNullStreams;
  private starting?: Promise<void>;
  private serial = 0;
  private pending = new Map<number, { resolve: (value: unknown) => void; reject: (error: Error) => void; timer: ReturnType<typeof setTimeout> }>();
  private listeners = new Set<{ message: (message: CodexMessage) => void; exit: (error: string) => void }>();
  constructor(private cwd: string, private enabled: boolean, private command = process.env.NEW_DIAGRAM_CODEX_BIN || 'codex') {}
  subscribe(message: (message: CodexMessage) => void, exit: (error: string) => void) {
    const entry = { message, exit }; this.listeners.add(entry); return () => { this.listeners.delete(entry); };
  }
  private start() {
    requireAiEnabled(this.enabled);
    if (this.starting) return this.starting;
    // Keep Agent Chat on threshold-based summarizing compaction, including resumed threads.
    // Process-local overrides take precedence over user/project config and model defaults.
    const child = spawn(this.command, [
      'app-server', '--listen', 'stdio://',
      '-c', 'model_auto_compact_token_limit_scope="total"',
      '-c', 'model_post_turn_compact_threshold_percent=0',
      '-c', 'features.token_budget.enabled=false',
      '-c', 'features.context_management.experimental_mode=false',
    ], { cwd: this.cwd, stdio: 'pipe' });
    this.child = child;
    // Drain stderr without exposing local configuration or credentials to the browser.
    child.stderr.resume();
    const lines = createInterface({ input: child.stdout });
    lines.on('line', line => {
      let message: { id?: number | string; method?: string; params?: Record<string, unknown>; error?: { message: string }; result?: unknown };
      try { message = JSON.parse(line); } catch { return; }
      if (message.method) {
        for (const listener of this.listeners) listener.message({ method: message.method, params: message.params ?? {}, id: message.id });
      } else if (typeof message.id === 'number') {
        const pending = this.pending.get(message.id); if (!pending) return;
        clearTimeout(pending.timer); this.pending.delete(message.id);
        if (message.error) pending.reject(new Error(message.error.message)); else pending.resolve(message.result);
      }
    });
    const failed = (message: string) => {
      if (this.child !== child) return;
      this.child = undefined; this.starting = undefined; lines.close();
      for (const pending of this.pending.values()) { clearTimeout(pending.timer); pending.reject(new Error(message)); }
      this.pending.clear();
      for (const listener of this.listeners) listener.exit(message);
    };
    child.once('error', error => failed(`Cannot start Codex: ${error.message}. Install Codex and run codex login on the server.`));
    child.once('exit', () => failed('Codex disconnected. Send another message to resume the conversation.'));
    child.stdin.on('error', () => failed('Codex input disconnected.'));
    this.starting = this.rpc('initialize', { clientInfo: { name: 'new_diagram', title: 'New Diagram', version: '0.1.0' }, capabilities: { experimentalApi: true } })
      .then(() => { this.write({ method: 'initialized' }); }).catch(error => { child.kill(); failed(String(error)); throw error; });
    return this.starting;
  }
  private write(message: unknown) {
    if (!this.child?.stdin.writable) throw new Error('Codex is disconnected.');
    this.child.stdin.write(`${JSON.stringify(message)}\n`);
  }
  private rpc<T>(method: string, params: Record<string, unknown>): Promise<T> {
    const id = ++this.serial;
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => { this.pending.delete(id); reject(new Error(`Codex ${method} timed out.`)); }, 30_000);
      this.pending.set(id, { resolve: value => resolve(value as T), reject, timer });
      try { this.write({ id, method, params }); } catch (error) { clearTimeout(timer); this.pending.delete(id); reject(error); }
    });
  }
  async request<T>(method: string, params: Record<string, unknown>): Promise<T> { await this.start(); return this.rpc<T>(method, params); }
  respond(id: string | number, result: unknown) { this.write({ id, result }); }
  reject(id: string | number, message: string) { this.write({ id, error: { code: -32601, message } }); }
  dispose() { this.child?.kill(); }
}
"},{"path":"infrastructure/mapping/agent-chat/chatMcpBinding.ts","text":"import path from 'node:path';
import type { AgentDiagrammingSessionService } from '../../../application/mapping/agent/sessionService';
import type { ChatCanvasTarget } from '../../../domain/mapping/agent-chat/agentChat';
import type { ChatMcpBinding } from '../../../application/mapping/agent-chat/ports';

export class MappingChatMcpBinding implements ChatMcpBinding {
  private tokens = new Map<string, string>();
  private origin?: string;
  private toolGenerations = new Map<string, string>();
  constructor(private agent: AgentDiagrammingSessionService, private appRoot: string) {}
  setOrigin(origin: string) { this.origin = origin; }
  chatId(token: string) { return [...this.tokens].find(([, value]) => value === token)?.[0]; }
  config(chatId: string, refreshTools = false) {
    if (!this.origin) throw Error('MCP_UNAVAILABLE: application address is not initialized');
    let token = this.tokens.get(chatId);
    if (!token) { token = this.agent.chatBindings.create(); this.tokens.set(chatId, token); }
    // A new runtime configuration also bypasses app-server's cached tool catalog.
    if (refreshTools) this.toolGenerations.set(chatId, crypto.randomUUID());
    const generation = this.toolGenerations.get(chatId);
    return { 'mcp_servers.mapping': { command: process.execPath,
      args: ['--import', 'tsx', path.join(this.appRoot, 'scripts/mapping/mcp.ts'), this.origin], cwd: this.appRoot,
      env: { MAPPING_CHAT_BINDING: token, ...(generation ? { MAPPING_TOOLS_GENERATION: generation } : {}) }, enabled: true } };
  }
  bind(chatId: string, target: ChatCanvasTarget | undefined, readOnly: boolean) {
    const token = this.tokens.get(chatId); if (!token) throw Error('CHAT_BINDING_UNAVAILABLE');
    this.agent.chatBindings.bind(token, target, readOnly);
  }
  clear(chatId: string) { const token = this.tokens.get(chatId); if (token) this.agent.chatBindings.clear(token); }
}
"},{"path":"infrastructure/core/agents/agentRuntime.ts","text":"import { requireAiEnabled } from '../../../application/core/errors';
import type { AgentContext } from '../../../domain/core/agents/agentContext';
import { type Model } from "@earendil-works/pi-ai";
import { createAgentSession, SessionManager, type CreateAgentSessionOptions, ModelRuntime, type AgentSessionEvent } from "@earendil-works/pi-coding-agent";
import { DEFAULT_DIAGRAM_MODEL_ID, type AgentProgress } from "../../../domain/core/records/domain";
export function progressFor(event: AgentSessionEvent, model: string, sessionId: string): AgentProgress | undefined {
  const shared = { model, sessionId };
  if (event.type === "agent_start" || event.type === "turn_start" || event.type === "message_start") {
    return { ...shared, status: "generating", message: "agent is composing a structured result" };
  }
  if (event.type === "tool_execution_start") {
    if (["read", "grep", "find", "ls"].includes(event.toolName)) {
      return { ...shared, status: "reading-context", message: `inspecting source with ${event.toolName}` };
    }
    if (event.toolName.startsWith("submit_")) {
      return { ...shared, status: "validating", message: "validating structured submission" };
    }
  }
  return undefined;
}
export function createPersistedAgentSessionManager(cwd: string): SessionManager {
  // Keep Pi sessions on disk so prompts, tool calls, and usage remain auditable.
  // Do not switch back to in-memory sessions without explicit user approval.
  return SessionManager.create(cwd);
}
export class PiAgentRuntime {
  constructor(private readonly enabled = false) {}

  protected requireEnabled(): void { requireAiEnabled(this.enabled); }

  protected modelRuntime?: Promise<ModelRuntime>;

  protected readonly sessions = new Set<{ abort(): Promise<void>; dispose(): void }>();

  protected async createSession(configuration: Omit<CreateAgentSessionOptions, 'sessionManager'>, context?: AgentContext) {
    this.requireEnabled();
    const sessionManager = createPersistedAgentSessionManager(configuration.cwd ?? process.cwd());
    for (const message of context?.toPiMessages() ?? []) sessionManager.appendMessage(message);
    const result = await createAgentSession({ ...configuration, sessionManager });
    this.sessions.add(result.session);
    return result;
  }

  protected runtime(): Promise<ModelRuntime> {
    this.requireEnabled();
    this.modelRuntime ??= ModelRuntime.create({ allowModelNetwork: false });
    return this.modelRuntime;
  }

  protected async model(overrideModelId?: string): Promise<{
    runtime: ModelRuntime;
    model: Model<any>;
    provider: string;
    modelId: string;
  }> {
    const runtime = await this.runtime();
    const provider = "openai-codex";
    const modelId = overrideModelId || process.env.NEW_DIAGRAM_MODEL || DEFAULT_DIAGRAM_MODEL_ID;
    const model = runtime.getModel(provider, modelId);
    if (!model) throw new Error(`Pi model is unavailable: ${provider}/${modelId}`);
    if (!runtime.hasConfiguredAuth(provider)) {
      throw new Error(`Pi provider is not authenticated: ${provider}`);
    }
    return { runtime, model, provider, modelId };
  }
  dispose(): void {
    for (const session of this.sessions) { void session.abort(); session.dispose(); }
    this.sessions.clear();
  }
}
"},{"path":"infrastructure/core/agents/validatedSubmission.ts","text":"export interface ValidatedSubmissionOptions<T> {
  toolName: string;
  validate(candidate: T): Promise<string | undefined> | string | undefined;
  acceptedMessage(candidate: T): string;
  acceptedDetails?(candidate: T): Record<string, unknown>;
  correctionPrompt?: string;
}

export function createValidatedSubmission<T>(options: ValidatedSubmissionOptions<T>) {
  let accepted: T | undefined;

  return {
    promptGuideline: `Call ${options.toolName} with the final candidate. If it is rejected, correct the reported issues and call it again.`,

    get value(): T | undefined {
      return accepted;
    },

    async execute(_toolCallId: string, candidate: T) {
      const validationError = await options.validate(candidate);
      if (validationError) {
        const correction = options.correctionPrompt
          ? `${options.correctionPrompt} Then call ${options.toolName} again.`
          : `Correct the submission and call ${options.toolName} again.`;
        return {
          content: [{
            type: "text" as const,
            text: `Submission rejected: ${validationError}. ${correction}`
          }],
          details: { accepted: false },
          terminate: false
        };
      }

      accepted = candidate;
      return {
        content: [{ type: "text" as const, text: options.acceptedMessage(candidate) }],
        details: {
          accepted: true,
          ...options.acceptedDetails?.(candidate)
        },
        terminate: true
      };
    }
  };
}
"},{"path":"infrastructure/mapping/agents/diagram-edit/diagramEditRuntime.ts","text":"import { diagramContentNodes } from '../../../../domain/core/diagrams/diagramContentNodes';
import { scopedReplacements } from '../../../../domain/core/diagrams/diagramSubtreeEdit';
import { captureDiagramAgentContext } from './diagramAgentContext';
import type { AgentContextSources } from '../../../../application/core/ports/agentContextSources';
import { AgentContext } from '../../../../domain/core/agents/agentContext';
import { Type } from '@earendil-works/pi-ai';
import { DefaultResourceLoader, defineTool, getAgentDir, SettingsManager } from '@earendil-works/pi-coding-agent';
import type { DiagramGenerationRequest, DiagramGenerator, GenerationOptions } from '../../../../domain/core/diagrams/diagramGeneration';
import { validateGeneratedDiagramEdit, type GeneratedDiagramEdit } from '../../../../domain/core/diagrams/generatedDiagramEdit';
import { diagramOutputFormat, defaultTemplateSelection, renderPromptTemplate, resolvePromptTemplate } from '../../../../domain/mapping/agent/promptTemplates';
import { PiAgentRuntime, progressFor } from '../../../core/agents/agentRuntime';
import { createValidatedSubmission } from '../../../core/agents/validatedSubmission';

/** Renders the request's validated template; requests without one use the default edit template. */
export function renderDiagramEditPrompt(request: DiagramGenerationRequest) {
  if (!request.context) throw Error('Diagram generation requires captured context');
  const prompt = request.prompt ?? (() => {
    const template = resolvePromptTemplate(defaultTemplateSelection(request.operation ?? 'edit-diagram'), request.operation ?? 'edit-diagram');
    return { markdown: template.markdown, options: template.options, parameters: template.definition.parameters, references: [] };
  })();
  const ranges = request.editRanges?.length ? request.editRanges : request.editRange ? [request.editRange] : [];
  return renderPromptTemplate(prompt, {
    context: JSON.stringify({ baseRevisionId: request.baseRevisionId ?? null, diagram: request.context.diagram, editableRanges: ranges,
      logicalNodes: request.baseRevisionId ? diagramContentNodes(request.context.diagram.content).map(node => ({ line: node.line, nodeRef: request.nodeRefs?.[node.id] })) : [],
      generationOptions: prompt.options, connections: request.context.connections ?? [] }),
